local TAU = 2 * math.pi
local NU, NV = 64, 24   -- grid resolution (u wraps, so 65/25 points emitted)

local surfaces = {
  {
    name = "torus",
    fn = function(u, v)
      local R, r = 2.0, 0.75
      return (R + r * math.cos(v)) * math.cos(u),
             r * math.sin(v),
             (R + r * math.cos(v)) * math.sin(u)
    end,
    vrange = { 0, TAU },
  },
  {
    name = "mobius",
    fn = function(u, v)
      -- v is the width coordinate; cos(u/2) gives the half-twist
      local w = v * 0.6
      return (2 + w * math.cos(u / 2)) * math.cos(u),
             w * math.sin(u / 2),
             (2 + w * math.cos(u / 2)) * math.sin(u)
    end,
    vrange = { -1, 1 },
  },
  {
    name = "klein",
    fn = function(u, v)
      -- figure-8 immersion of the Klein bottle
      local a = 2.0
      local c2, s2 = math.cos(u / 2), math.sin(u / 2)
      local sv, s2v = math.sin(v), math.sin(2 * v)
      return (a + c2 * sv - s2 * s2v) * math.cos(u),
             s2 * sv + c2 * s2v,
             (a + c2 * sv - s2 * s2v) * math.sin(u)
    end,
    vrange = { 0, TAU },
  },
}

local parts = {}
for _, s in ipairs(surfaces) do
  local coords = {}
  for i = 0, NU do
    local u = TAU * i / NU
    for j = 0, NV do
      local v = s.vrange[1] + (s.vrange[2] - s.vrange[1]) * j / NV
      local x, y, z = s.fn(u, v)
      coords[#coords + 1] = string.format("%d,%d,%d",
        math.floor(x * 100 + 0.5), math.floor(y * 100 + 0.5), math.floor(z * 100 + 0.5))
    end
  end
  parts[#parts + 1] = '{"name":"' .. s.name .. '","nu":' .. (NU + 1) ..
    ',"nv":' .. (NV + 1) .. ',"pts":[' .. table.concat(coords, ",") .. ']}'
  print(string.format("%-7s sampled %dx%d = %d vertices", s.name, NU + 1, NV + 1, (NU + 1) * (NV + 1)))
end

print('__NB_SET__ {"key":"surfaces","value":{"scale":100,"list":[' ..
  table.concat(parts, ",") .. ']}}')
